private function resolvePayrollRule(?int $branchId, ?PayrollMonthStatus $lockRow): array
{
    if (!$branchId) {
        return [];
    }
    if ($lockRow && $lockRow->status === 'locked' && $lockRow->rule_version_id) {
        return PayrollBranchRule::resolveForLockedMonth($branchId, $lockRow->rule_version_id);
